-- SSMS: wybierz kopię bazy podmiotu. Najpierw uruchom z @Zapisz = 0.
-- Po sprawdzeniu podglądu ustaw @Zapisz = 1 i uruchom ponownie.
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @Zapisz bit = 0;

IF NOT EXISTS (
    SELECT 1 FROM dbo.tw__Towar
    WHERE tw_Symbol = N'A421206' AND LTRIM(RTRIM(tw_Pole2)) = N'19802'
)
    THROW 50001, N'Brak wpisu próbnego A421206 = 19802 w polu 2.', 1;

DROP TABLE IF EXISTS #Rpl;
DROP TABLE IF EXISTS #Dopasowane;
CREATE TABLE #Rpl (
    Symbol nvarchar(255) COLLATE DATABASE_DEFAULT NOT NULL,
    IdRpl nvarchar(16) NOT NULL
);



-- Kartoteki zweryfikowane w katalogu ze statusem RPL PL.

;WITH Mapowanie AS (
    SELECT Symbol, MIN(IdRpl) AS IdRpl
    FROM #Rpl GROUP BY Symbol HAVING COUNT(DISTINCT IdRpl) = 1
),
JednoznaczneTowary AS (
    SELECT tw_Symbol FROM dbo.tw__Towar
    GROUP BY tw_Symbol HAVING COUNT(*) = 1
)
SELECT t.tw_Id, t.tw_Symbol, t.tw_Nazwa, t.tw_Pole2, m.IdRpl
INTO #Dopasowane
FROM Mapowanie m
JOIN JednoznaczneTowary u ON u.tw_Symbol = m.Symbol
JOIN dbo.tw__Towar t ON t.tw_Symbol = u.tw_Symbol;

SELECT tw_Symbol, tw_Nazwa, IdRpl AS [ID RPL do wpisania]
FROM #Dopasowane WHERE NULLIF(LTRIM(RTRIM(tw_Pole2)), N'') IS NULL
ORDER BY tw_Symbol;

SELECT tw_Symbol, tw_Nazwa, tw_Pole2 AS [Obecne ID], IdRpl AS [ID z katalogu]
FROM #Dopasowane
WHERE NULLIF(LTRIM(RTRIM(tw_Pole2)), N'') IS NOT NULL
  AND LTRIM(RTRIM(tw_Pole2)) <> IdRpl
ORDER BY tw_Symbol;

SELECT DISTINCT r.Symbol AS [Symbol bez jednoznacznego dopasowania]
FROM #Rpl r WHERE NOT EXISTS (SELECT 1 FROM #Dopasowane d WHERE d.tw_Symbol = r.Symbol)
ORDER BY r.Symbol;

IF @Zapisz = 1
BEGIN
    BEGIN TRANSACTION;
    UPDATE t SET tw_Pole2 = d.IdRpl
    FROM dbo.tw__Towar t
    JOIN #Dopasowane d ON d.tw_Id = t.tw_Id AND d.tw_Symbol = t.tw_Symbol
    WHERE NULLIF(LTRIM(RTRIM(t.tw_Pole2)), N'') IS NULL;
    DECLARE @Zmienione int = @@ROWCOUNT;
    COMMIT TRANSACTION;
    SELECT @Zmienione AS [Uzupełnione kartoteki];
END;

DROP TABLE #Dopasowane;
DROP TABLE #Rpl;
